/* Groups 15/16. Pure presentation, no persistence, runtime services, listeners or clocks. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.NutriHealthCompanionGlass=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rows=v=>Array.isArray(v)?v.filter(x=>x&&typeof x==='object'):[];
const date=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!isNaN(Date.parse(v+'T12:00:00Z'))&&new Date(v+'T12:00:00Z').toISOString().slice(0,10)===v?v:'';
const time=v=>typeof v==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(v)?v:'时间未提供';
const finite=v=>typeof v==='number'&&Number.isFinite(v)?v:'未知';
const button=(label,action,id)=>`<button type="button" class="hcg-button" data-hd="${esc(action)}"${id===undefined?'':` data-id="${esc(id)}"`}>${esc(label)}</button>`;
const card=body=>`<section class="hcg-card">${body}</section>`;
const notice=text=>`<p class="hcg-notice">${esc(text)}</p>`;
const shell=(title,sub,body)=>`<div class="hcg-view"><header class="hcg-heading"><span class="hcg-eyebrow">本机合成演示</span><h2>${esc(title)}</h2><p>${esc(sub)}</p></header>${body}</div>`;
const fields=[['appearance','望 · 自述外观或精神感受'],['voice','闻 · 自述声音或呼吸感受'],['sleep','问 · 睡眠情况'],['appetite','问 · 食欲与饮食'],['feeling','问 · 其他感受']];
function renderDaily({health={}}={}){const notes=rows(health.dailyNotes);return shell('日常自述','只整理自述，不检测、不诊断。',notice('请只录入合成资料。没有图像、语音、气味或脉象检测，不提供中医辨证、体质评分或个性化建议。')+card(`<h3>记录这一天</h3><form data-form="daily"><label>日期<input name="date" type="date" value="${esc(date(health.demoDate))}" required></label>${fields.map(([k,label])=>`<label>${label}<input name="${k}" maxlength="120" placeholder="合成示例，可留空"></label>`).join('')}<p class="hcg-muted">切诊：未采集，不提供模拟脉诊结论。空白表示未填写。</p><label class="hcg-check"><input name="confirm" type="checkbox" required>我仅录入合成资料并保存在本机</label><button class="hcg-primary" type="submit">保存日常自述</button></form>`)+card(`<div class="hcg-section-title"><h3>已保存自述</h3><span>${notes.length} 条</span></div>${notes.length?`<ol class="hcg-history">${notes.slice().reverse().map(n=>`<li><h4>${esc(date(n.date)||'日期未提供')}</h4><dl>${fields.map(([k,label])=>`<div><dt>${label}</dt><dd>${esc(n[k]||'未填写')}</dd></div>`).join('')}</dl><small>${esc(n.source||'来源未填写')} · 合成自述</small></li>`).join('')}</ol>`:notice('尚未填写；未填写不代表没有异常。')}`));}
function reminderSource(r){if(r.kind!=='medication')return r.source||'来源未填写';return r.enteredBy==='instruction'?'既有医嘱录入（合成、未验证）':r.enteredBy==='user'?'用户自录（合成、未验证）':'来源未明确；编辑时需选择';}
function renderReminders({health={},editId}={}){const list=rows(health.reminders),edit=list.find(r=>r.id===editId);if(editId&&!edit)return shell('本页提醒','这条记录已不存在',notice('请重新选择当前记录；不创建替代安排。'));const active=list.filter(r=>!r.withdrawn&&r.enabled!==false).length,paused=list.filter(r=>!r.withdrawn&&r.enabled===false).length,withdrawn=list.filter(r=>r.withdrawn).length;return shell('本页提醒计划','记录既有合成安排，不提供处方或后台通知。',notice('关闭页面不会提醒；打卡不证明真实服药或进餐。暂停或撤回提醒不表示停药。')+`<div class="hcg-stats"><div class="hcg-stat"><small>已启用</small><strong>${active}</strong></div><div class="hcg-stat"><small>已暂停</small><strong>${paused}</strong></div><div class="hcg-stat"><small>已撤回</small><strong>${withdrawn}</strong></div></div>`+card(`<h3>已有安排 · ${list.length} 条</h3>${list.length?`<ul class="hcg-reminders">${list.map(r=>`<li><div class="hcg-reminder-top"><span class="hcg-reminder-icon" aria-hidden="true">${({water:'◉',meal:'◷',medication:'＋'})[r.kind]||'○'}</span><div><strong>${esc(r.label||'名称未填写')}</strong><small>${esc(({water:'饮水',meal:'餐食',medication:'用药自录'})[r.kind]||'类型未知')} · ${r.withdrawn?'已撤回':r.enabled===false?'已暂停':'已启用'}</small></div><time>${esc(time(r.time))}</time></div><p class="hcg-muted">${esc(reminderSource(r))}</p><div class="hcg-actions">${button(r.withdrawn?'编辑并恢复':'编辑','edit-reminder',r.id)}${r.withdrawn?'':button(r.enabled===false?'恢复启用':'暂停','toggle-reminder',r.id)+button('撤回','withdraw-reminder',r.id)}</div></li>`).join('')}</ul>`:notice('尚无已保存安排；没有默认创建提醒。')}`)+card(`<h3>${edit?'编辑合成安排':'新增合成安排'}</h3>${edit?.withdrawn?notice('保存将恢复此条目但保持暂停；需再明确点击恢复启用。历史打卡保留。'):''}<form data-form="reminder" data-edit-id="${esc(edit?.id||'')}"><div class="hcg-fields"><label>类型<select name="kind">${[['meal','吃饭'],['water','喝水'],['medication','用药自录']].map(([v,l])=>`<option value="${v}"${edit?.kind===v?' selected':''}>${l}</option>`).join('')}</select></label><label>时间<input type="time" name="time" value="${time(edit?.time)==='时间未提供'?'':esc(edit.time)}" required></label></div><label>提醒名称<input name="label" value="${esc(edit?.label||'')}" maxlength="80" required placeholder="仅合成名称；不填写真实药品与剂量"></label><label>用药安排来源（用药项必选）<select name="enteredBy"><option value="">请选择，不由系统推断</option>${[['user','用户自录（合成、未验证）'],['instruction','既有医嘱录入（合成、未验证）']].map(([v,l])=>`<option value="${v}"${edit?.kind==='medication'&&edit?.enteredBy===v?' selected':''}>${l}</option>`).join('')}</select></label><p class="hcg-muted">不推荐药品、剂量或停药，不验证医嘱来源。旧预设药物也必须重新明确来源。每条安排只有一个时间，不支持工作日或自定义重复。</p><label class="hcg-check"><input name="confirm" type="checkbox" required>确认只使用合成既有安排，不是系统处方</label><div class="hcg-actions"><button class="hcg-primary" type="submit">${edit?.withdrawn?'保存并恢复为暂停':edit?'保存修改':'新增提醒'}</button>${button('取消填写','cancel-reminder')}</div></form>`));}
function messageCard(m,health,model){if(m.kind==='recipes')return card(`<h3>通用食谱示例</h3><p>先核对过敏原与医嘱限制；选食谱不等于进食。</p><div class="hcg-actions">${rows(model.RECIPES).map(r=>button(r.name,'recipe',r.id)).join('')}</div>${button('全部食谱','recipes')}`);if(m.kind==='report'){const water=rows(health.water).filter(r=>r.date===health.demoDate),knownWater=water.filter(r=>typeof r.ml==='number'&&Number.isFinite(r.ml)),sameDay=rows(health.meals).filter(r=>r.date===health.demoDate),w=rows(health.metrics).filter(r=>r.metric==='weight'&&typeof r.value==='number'&&Number.isFinite(r.value)&&date(r.date)&&r.unit==='kg').slice().sort((a,b)=>a.date.localeCompare(b.date));return card(`<h3>今天的小回顾</h3><p>${esc(date(health.demoDate)||'日期未提供')} · 合成记录，非 AI 分析</p><p>本演示日已记录 ${sameDay.length} 餐。</p><p>演示饮水已知合计 ${knownWater.length?finite(knownWater.reduce((sum,r)=>sum+r.ml,0)):'未知'} ml · 有值 ${knownWater.length}/${water.length} 条。</p><p>最近体重记录 ${finite(w.at(-1)?.value)} kg${w.length?' · '+esc(w.at(-1).date):''}。变化不等于健康判断或疗效。</p><div class="hcg-actions">${button('看指标趋势','metrics')}${button('看饮食记录','records')}</div>`);}if(m.kind==='reminders'){const enabled=rows(health.reminders).filter(r=>r.enabled!==false&&!r.withdrawn),checks=rows(health.reminderChecks).filter(c=>c.date===health.demoDate);return card(`<h3>今日合成提醒</h3><p>${esc(date(health.demoDate)||'日期未提供')} · 仅本页提醒，关闭后不会通知。</p><ul class="hcg-reminders">${enabled.map(r=>`<li><strong>${esc(r.label)}</strong><small>${esc(time(r.time))} · ${esc(reminderSource(r))}</small>${checks.some(c=>c.reminderId===r.id)?'<span class="hcg-pill">本演示日已打卡</span>':button('打卡','check',r.id)}</li>`).join('')}</ul>${enabled.length?'':notice('本演示日没有启用的合成安排。')}${notice('打卡不证明真实服药或进餐；暂停或撤回不表示停药。')}${button('管理提醒','reminders')}`);}if(m.kind==='water')return card('<h3>喝水，记一小步</h3><p>明确确认后才增加记录，聊天文字不会自动计量。限液安排遵从专业人员。</p>'+button('记录演示饮水','water'));return '';}
function renderMessages({health={},model={}}={}){const messages=rows(health.messages);return `<div class="hcg-view hcg-chat"><p class="hcg-day">${esc(date(health.demoDate)||'日期未提供')} · 合成账号</p>${messages.length?messages.map(m=>`<article class="hcg-message ${m.role==='user'?'hcg-user':'hcg-assistant'}"><div class="hcg-avatar" aria-hidden="true">${m.role==='user'?'我':m.role==='assistant'?'禾':'·'}</div><div class="hcg-bubble"><span class="hcg-message-role">${m.role==='user'?'合成账号输入':m.role==='assistant'?(m.source==='synthetic-fixture'?'预设合成对话':m.source==='local-rule-reply'||m.source==='local-rule-report'?'本机规则回复':'来源未确认'):'消息类型未确认'}</span><p class="hcg-message-text">${esc(m.text)}</p>${Array.isArray(m.choices)&&m.choices.length?`<div class="hcg-actions">${m.choices.map(t=>`<button type="button" class="hcg-button" data-hd="say" data-text="${esc(t)}">${esc(t)}</button>`).join('')}</div>`:''}<time>${esc(date(m.date)||'日期未提供')} ${esc(time(m.time))} · ${m.source==='synthetic-fixture'?'预设合成对话':m.role==='user'?'本机演示输入':m.source==='local-rule-reply'||m.source==='local-rule-report'?'规则回复':'来源未确认'}</time></div></article>${messageCard(m,health,model)}`).join(''):notice('暂无已保存对话。输入框中的未发送文字不是已保存记录。')}</div>`;}
function renderServiceStatus({health={},storageMode='unknown'}={}){const storage=storageMode==='persistent'?'已连接本机持久存储；已核验提交才算保存。':storageMode==='memory'?'仅当前页面内存；刷新或离开后会丢失。':'存储模式尚未核对，请以当前账号状态为准。';return shell('服务与保存状态','本机规则演示，不是在线营养服务。',card(`<div class="hcg-service-hero"><span aria-hidden="true">◇</span><div><h3>AI 服务未连接</h3><p>仍可使用有限关键词的本机规则回复。</p></div></div><p>当前演示日：${esc(date(health.demoDate)||'日期未提供')}</p>`)+card(`<ul class="hcg-list">${[['大模型','未配置 · 当前为规则'],['语音交互','未配置 · 无录音'],['菜品识别','未配置 · 无上传'],['后台提醒','未配置 · 关闭页面不提醒'],['真人营养师','未连接 · 无发送'],['数字形象','静态原创形象 · 无实时驱动']].map(([k,v])=>`<li><strong>${k}</strong><span>${v}</span></li>`).join('')}</ul>`)+notice(storage)+card('<h3>消息与未发送填写</h3><p>明确发送后才尝试保存本机演示对话；未发送内容仅是本页填写，不保证刷新或离开后保留。</p><p>AI 未连接不等于本机保存失败。没有核验回执时，结果仍待核对，不显示成功或失败结论。</p><p class="hcg-muted">真实保存、原请求重试、账号重置与恢复由当前控制器和账号入口处理。</p>'));}
return Object.freeze({renderDaily,renderReminders,renderMessages,renderServiceStatus});
});
